var ring = root.querySelector('.mtu-magnetic-dot-ring');
var out = root.querySelector('.mtu-magnetic-dot-out');
var btns = Array.prototype.slice.call(root.querySelectorAll('.mtu-magnetic-dot-btn'));
var mq = window.matchMedia('(prefers-reduced-motion: reduce)');
var cur = { x: 40, y: 40, w: 15, h: 15, r: 8 };
var tgt = { x: 40, y: 40, w: 15, h: 15, r: 8 };
var vis = 0, want = 0, raf = 0, idle = 'Pick a format — the pointer snaps to each target.';

function paint() {
  ring.style.width = cur.w.toFixed(1) + 'px';
  ring.style.height = cur.h.toFixed(1) + 'px';
  ring.style.borderRadius = cur.r.toFixed(1) + 'px';
  ring.style.transform = 'translate3d(' + (cur.x - cur.w / 2).toFixed(1) + 'px,' + (cur.y - cur.h / 2).toFixed(1) + 'px,0)';
  ring.style.opacity = vis.toFixed(3);
}

function tick() {
  if (!root.isConnected) { raf = 0; return; }
  var k = 0.26;
  cur.x += (tgt.x - cur.x) * k;
  cur.y += (tgt.y - cur.y) * k;
  cur.w += (tgt.w - cur.w) * 0.22;
  cur.h += (tgt.h - cur.h) * 0.22;
  cur.r += (tgt.r - cur.r) * 0.22;
  vis += (want - vis) * 0.2;
  paint();
  var rest = Math.abs(tgt.x - cur.x) + Math.abs(tgt.y - cur.y) + Math.abs(tgt.w - cur.w) + Math.abs(want - vis) * 40;
  raf = (want || rest > 0.35) ? requestAnimationFrame(tick) : 0;
}

function wake() { if (!raf && !mq.matches) raf = requestAnimationFrame(tick); }

function boxOf(el) {
  var r0 = root.getBoundingClientRect(), b = el.getBoundingClientRect();
  return { x: b.left - r0.left + b.width / 2, y: b.top - r0.top + b.height / 2, w: b.width + 12, h: b.height + 10, r: 12 };
}

function aim(mx, my) {
  var hit = null, r0 = root.getBoundingClientRect(), i, b, bx, by;
  for (i = 0; i < btns.length; i++) {
    if (btns[i].disabled) continue;
    b = btns[i].getBoundingClientRect();
    bx = b.left - r0.left; by = b.top - r0.top;
    if (mx >= bx - 7 && mx <= bx + b.width + 7 && my >= by - 7 && my <= by + b.height + 7) { hit = btns[i]; break; }
  }
  if (hit) {
    tgt = boxOf(hit);
    ring.classList.add('mtu-magnetic-dot-ring-on');
    out.textContent = hit.getAttribute('data-mtu-meta');
  } else {
    tgt = { x: mx, y: my, w: 15, h: 15, r: 8 };
    ring.classList.remove('mtu-magnetic-dot-ring-on');
    out.textContent = idle;
  }
}

root.addEventListener('pointermove', function (e) {
  if (mq.matches) return;
  var r0 = root.getBoundingClientRect();
  aim(e.clientX - r0.left, e.clientY - r0.top);
  want = 1;
  wake();
});
root.addEventListener('pointerleave', function () {
  want = 0;
  ring.classList.remove('mtu-magnetic-dot-ring-on');
  out.textContent = idle;
  wake();
});
btns.forEach(function (b) {
  b.addEventListener('focus', function () {
    if (mq.matches) return;
    if (!b.disabled) { tgt = boxOf(b); ring.classList.add('mtu-magnetic-dot-ring-on'); }
    out.textContent = b.getAttribute('data-mtu-meta');
    want = 1; wake();
  });
  b.addEventListener('blur', function () { want = 0; out.textContent = idle; wake(); });
  b.addEventListener('click', function () {
    out.textContent = 'Exporting hero-frame.' + b.textContent.toLowerCase() + ' …';
  });
});
paint();

