var glow = root.querySelector('.mtu-lag-blob-glow');
var tip = root.querySelector('.mtu-lag-blob-tip');
var note = root.querySelector('.mtu-lag-blob-note');
var tiles = Array.prototype.slice.call(root.querySelectorAll('.mtu-lag-blob-tile'));
var mq = window.matchMedia('(prefers-reduced-motion: reduce)');
var px = 0, py = 0, gx = 0, gy = 0, tx = 0, ty = 0, pgx = 0, pgy = 0;
var inside = false, scale = 1, raf = 0, idle = 'Hover a look';

function tick() {
  if (!root.isConnected) { raf = 0; return; }
  gx += (px - gx) * 0.08;
  gy += (py - gy) * 0.08;
  tx += (px - tx) * 0.45;
  ty += (py - ty) * 0.45;
  var vx = gx - pgx, vy = gy - pgy;
  pgx = gx; pgy = gy;
  var sp = Math.min(1, Math.sqrt(vx * vx + vy * vy) / 26);
  var ang = (vx || vy) ? Math.atan2(vy, vx) * 180 / Math.PI : 0;
  var want = inside ? 1 : 0.72;
  scale += (want - scale) * 0.12;
  glow.style.transform = 'translate3d(' + gx.toFixed(1) + 'px,' + gy.toFixed(1) + 'px,0) rotate(' + ang.toFixed(1) + 'deg) scale(' + (scale * (1 + sp * 0.55)).toFixed(3) + ',' + (scale * (1 - sp * 0.34)).toFixed(3) + ')';
  tip.style.transform = 'translate3d(' + tx.toFixed(1) + 'px,' + ty.toFixed(1) + 'px,0)';
  var rest = Math.abs(px - gx) + Math.abs(py - gy) + Math.abs(1 - scale) * 30;
  raf = (inside || rest > 0.4) ? requestAnimationFrame(tick) : 0;
}

function wake() { if (!raf && !mq.matches) raf = requestAnimationFrame(tick); }

root.addEventListener('pointerenter', function (e) {
  if (mq.matches) return;
  var r0 = root.getBoundingClientRect();
  gx = px = e.clientX - r0.left; tx = px; pgx = gx;
  gy = py = e.clientY - r0.top; ty = py; pgy = gy;
  inside = true;
  glow.style.opacity = '1';
  tip.style.opacity = '1';
  wake();
});
root.addEventListener('pointermove', function (e) {
  if (mq.matches) return;
  var r0 = root.getBoundingClientRect();
  px = e.clientX - r0.left;
  py = e.clientY - r0.top;
  if (!inside) { gx = tx = pgx = px; gy = ty = pgy = py; }
  inside = true;
  glow.style.opacity = '1';
  tip.style.opacity = '1';
  wake();
});
root.addEventListener('pointerleave', function () {
  inside = false;
  glow.style.opacity = '0';
  tip.style.opacity = '0';
  note.textContent = idle;
  root.style.removeProperty('--mtu-lb-h');
  wake();
});
tiles.forEach(function (t) {
  function on() {
    root.style.setProperty('--mtu-lb-h', t.getAttribute('data-mtu-hue'));
    note.textContent = t.getAttribute('data-mtu-note');
  }
  t.addEventListener('pointerenter', on);
  t.addEventListener('focus', on);
  t.addEventListener('blur', function () { note.textContent = idle; });
  t.addEventListener('click', function () {
    note.textContent = t.querySelector('.mtu-lag-blob-name').textContent + ' added to the bag';
  });
});

