var stage = root.querySelector('.mtu-spotlight-reveal-stage');
var halo = root.querySelector('.mtu-spotlight-reveal-halo');
var btn = root.querySelector('.mtu-spotlight-reveal-btn');
var hint = root.querySelector('.mtu-spotlight-reveal-hint');
var mq = window.matchMedia('(prefers-reduced-motion: reduce)');
var open = false, wide = false;

function put(e) {
  var r0 = stage.getBoundingClientRect();
  var x = e.clientX - r0.left, y = e.clientY - r0.top;
  stage.style.setProperty('--mtu-sr-x', x.toFixed(1) + 'px');
  stage.style.setProperty('--mtu-sr-y', y.toFixed(1) + 'px');
  stage.style.setProperty('--mtu-sr-r', wide ? '104px' : '74px');
  halo.style.transform = 'translate3d(' + x.toFixed(1) + 'px,' + y.toFixed(1) + 'px,0)';
  halo.style.opacity = '1';
  hint.textContent = 'Decoding';
}

stage.addEventListener('pointerenter', function (e) {
  if (mq.matches || open) return;
  put(e);
});
stage.addEventListener('pointermove', function (e) {
  if (mq.matches || open) return;
  put(e);
});
stage.addEventListener('pointerleave', function () {
  if (open) return;
  stage.style.setProperty('--mtu-sr-r', '0px');
  halo.style.opacity = '0';
  hint.textContent = 'Sweep the pointer to read';
});
stage.addEventListener('pointerdown', function (e) {
  if (mq.matches || open) return;
  wide = true; put(e);
});
stage.addEventListener('pointerup', function (e) {
  if (mq.matches || open) return;
  wide = false; put(e);
});
btn.addEventListener('click', function () {
  open = !open;
  root.classList.toggle('mtu-spotlight-reveal-open', open);
  btn.setAttribute('aria-pressed', open ? 'true' : 'false');
  btn.textContent = open ? 'Hide again' : 'Reveal all';
  hint.textContent = open ? 'Full report visible' : 'Sweep the pointer to read';
  if (!open) { stage.style.setProperty('--mtu-sr-r', '0px'); halo.style.opacity = '0'; }
});

