var layer = root.querySelector('.mtu-click-ripple-layer');
var halo = root.querySelector('.mtu-click-ripple-halo');
var out = root.querySelector('.mtu-click-ripple-out');
var btn = root.querySelector('.mtu-click-ripple-clear');
var nodes = Array.prototype.slice.call(root.querySelectorAll('.mtu-click-ripple-node'));
var mq = window.matchMedia('(prefers-reduced-motion: reduce)');
var n = 0;

function flash(x, y) {
  var r0 = root.getBoundingClientRect(), i, b, cx, cy, d;
  for (i = 0; i < nodes.length; i++) {
    b = nodes[i].getBoundingClientRect();
    cx = b.left - r0.left + b.width / 2;
    cy = b.top - r0.top + b.height / 2;
    d = Math.sqrt((cx - x) * (cx - x) + (cy - y) * (cy - y));
    if (d < 84) {
      (function (el, delay) {
        setTimeout(function () {
          el.classList.add('mtu-click-ripple-node-hit');
          setTimeout(function () { el.classList.remove('mtu-click-ripple-node-hit'); }, 320);
        }, delay);
      })(nodes[i], d * 2.6);
    }
  }
}

function ping(x, y) {
  n += 1;
