  pts.push({ x: 0, y: 0 });
  dots[i].style.background = 'hsl(' + (330 - i * 5) + ',92%,' + (72 - i * 1.6).toFixed(0) + '%)';
  dots[i].style.boxShadow = i < 4 ? '0 0 14px 1px hsla(' + (330 - i * 5) + ',92%,64%,.75)' : 'none';
}

function tick(now) {
  if (!root.isConnected) { raf = 0; return; }
  pts[0].x += (px - pts[0].x) * 0.34;
  pts[0].y += (py - pts[0].y) * 0.34;
  for (var i = 1; i < n; i++) {
    pts[i].x += (pts[i - 1].x - pts[i].x) * 0.36;
    pts[i].y += (pts[i - 1].y - pts[i].y) * 0.36;
  }
  shown += ((inside ? 1 : 0) - shown) * 0.12;
  for (var j = 0; j < n; j++) {
    var t = 1 - j / n;
    dots[j].style.opacity = (shown * (0.14 + t * 0.8)).toFixed(3);
    dots[j].style.transform = 'translate3d(' + pts[j].x.toFixed(1) + 'px,' + pts[j].y.toFixed(1) + 'px,0) scale(' + (0.2 + t * 0.85).toFixed(3) + ')';
  }
  if (now - lastT > 110) {
    var dx = pts[0].x - lastX, dy = pts[0].y - lastY;
    var d = Math.sqrt(dx * dx + dy * dy);
    speedEl.textContent = Math.round(d / Math.max(0.001, (now - lastT) / 1000));
    dist += d;
    distEl.textContent = Math.round(dist);
    lastX = pts[0].x; lastY = pts[0].y; lastT = now;
  }
  var rest = Math.abs(px - pts[n - 1].x) + Math.abs(py - pts[n - 1].y) + shown * 20;
  raf = (inside || rest > 0.6) ? requestAnimationFrame(tick) : 0;
}

function wake() { if (!raf && !mq.matches) { lastT = performance.now(); raf = requestAnimationFrame(tick); } }

root.addEventListener('pointerenter', function (e) {
  if (mq.matches) return;
  var r0 = root.getBoundingClientRect();
  px = e.clientX - r0.left; py = e.clientY - r0.top;
  for (var i = 0; i < n; i++) { pts[i].x = px; pts[i].y = py; }
  lastX = px; lastY = py;
  inside = true;
  wake();
});
root.addEventListener('pointermove', function (e) {
  if (mq.matches) return;
  var r0 = root.getBoundingClientRect();
  px = e.clientX - r0.left;
  py = e.clientY - r0.top;
  if (!inside) {
    for (var i = 0; i < n; i++) { pts[i].x = px; pts[i].y = py; }
    lastX = px; lastY = py;
  }
  inside = true;
  wake();
});
root.addEventListener('pointerleave', function () {
  inside = false;
  speedEl.textContent = '0';
  wake();
});
reset.addEventListener('click', function () {
  dist = 0;
  distEl.textContent = '0';
  speedEl.textContent = '0';
});
